85	    @Column(name = "possible_duplicate", nullable = false)
86	    private boolean possibleDuplicate;
87	
88	    @Column(name = "possible_duplicate_of")
89	    private Integer possibleDuplicateOf;
90	
91	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
92	    private Set<Pet> pets;
93	
94	    public String getAddress() {
95	        return this.address;
96	    }
97	
98	    public void setAddress(String address) {
99	        this.address = address;
100	    }
101	
102	    public String getCity() {
103	        return this.city;
104	    }
105	
