108	    }
109	
110	    public String getTelephone() {
111	        return this.telephone;
112	    }
113	
114	    public void setTelephone(String telephone) {
115	        this.telephone = telephone;
116	    }
117	
118	    public String getEmail() {
119	        return this.email;
120	    }
121	
122	    public void setEmail(String email) {
123	        this.email = email;
124	    }
125	
126	    /**
127	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
128	     * against the city's region and then stored verbatim. Optional, so may be null.
129	     */
130	    public String getPostcode() {
131	        return this.postcode;
132	    }
133	
134	    public void setPostcode(String postcode) {
135	        this.postcode = postcode;
136	    }
137	
138	    public LocalDate getRegistrationDate() {
139	        return this.registrationDate;
140	    }
141	
142	    public void setRegistrationDate(LocalDate registrationDate) {
143	        this.registrationDate = registrationDate;
144	    }
145	
146	    /**
147	     * The owner's date of birth. Optional, so may be null.
148	     */
149	    public LocalDate getBirthDate() {
150	        return this.birthDate;
151	    }
152	
153	    public void setBirthDate(LocalDate birthDate) {
154	        this.birthDate = birthDate;
155	    }
156	
157	    /**
158	     * The owner's age band as at registration: {@code "MINOR"} for under 18,
159	     * {@code "ADULT"} for 18 to 64, or {@code "SENIOR"} for 65 and over, measured from the
160	     * birth date against the registration date. Null when no birth date is recorded.
161	     * Derived from stored state, never persisted.
162	     */
163	    public String getAgeBand() {
164	        if (this.birthDate == null || this.registrationDate == null) {
165	            return null;
166	        }
167	        return AgeBand.of(this.birthDate, this.registrationDate);
168	    }
169	
170	    public String getCustomerCode() {
171	        return this.customerCode;
172	    }
173	
174	    public void setCustomerCode(String customerCode) {
175	        this.customerCode = customerCode;
176	    }
177	
178	    /**
179	     * The stable identifier of the household this owner belongs to: the first twelve hex
180	     * characters of the SHA-256 of the normalized last name and postcode, so every owner
181	     * sharing a last name and postcode resolves to the same value. Null when the owner has
182	     * no postcode. Assigned at creation.
183	     */
184	    public String getHouseholdId() {
185	        return this.householdId;
186	    }
187	
188	    public void setHouseholdId(String householdId) {
