213	        this.membershipNumber = membershipNumber;
214	    }
215	
216	    /**
217	     * Whether this owner was created as part of a bulk signup: {@code true} when more
218	     * than 80 owners had already been registered on this owner's registration date at
219	     * the moment it was created, {@code false} otherwise. Captured at creation.
220	     */
221	    public boolean isBulkSignupWarning() {
222	        return this.bulkSignupWarning;
223	    }
224	
225	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
226	        this.bulkSignupWarning = bulkSignupWarning;
227	    }
228	
229	    /**
230	     * Whether this owner resembles an existing one: {@code true} when, at creation, it
231	     * shared an existing owner's household (same last name and postcode, hence the same
232	     * {@link #getHouseholdId() household id}) while having a different telephone and was not
233	     * a declared household member, {@code false} otherwise. A declared member (created with
234	     * {@code sharesHousehold}) is a genuine member, not a suspected duplicate. When true,
235	     * {@link #getPossibleDuplicateOf()} holds that owner's id. Captured at creation.
236	     */
237	    public boolean isPossibleDuplicate() {
238	        return this.possibleDuplicate;
239	    }
240	
241	    public void setPossibleDuplicate(boolean possibleDuplicate) {
242	        this.possibleDuplicate = possibleDuplicate;
243	    }
244	
245	    /**
246	     * The id of the existing owner this owner possibly duplicates (same household — last
247	     * name and postcode — different telephone), or null when it is not a possible
248	     * duplicate. Captured at creation.
249	     */
250	    public Integer getPossibleDuplicateOf() {
251	        return this.possibleDuplicateOf;
252	    }
253	
254	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
255	        this.possibleDuplicateOf = possibleDuplicateOf;
256	    }
257	
258	    /**
259	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
260	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
261	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
262	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
263	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
264	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
265	     * region is derived directly from the stored postcode and city. Derived from stored
266	     * state, never persisted.
267	     */
268	    public String getLocality() {
269	        String region = CustomerCode.regionOf(this.customerCode);
270	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
271	    }
272	
273	    /**
274	     * The owner's membership level, from 1 to 3: starts at 1, gains 1 when this owner has
275	     * an email address, and gains 1 when this owner had no namesakes at creation
276	     * ({@code namesakeCount} is 0). Capped at 3 (level 4 is reserved for tenure). Derived
277	     * from stored state, never persisted.
278	     */
279	    public int getMembershipLevel() {
280	        int level = 1;
281	        if (hasEmail()) {
282	            level++;
283	        }
284	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
285	            level++;
286	        }
287	        return Math.min(level, 3);
288	    }
289	
290	    /**
291	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
292	     * the {@code customerCode}. Derived from stored state, never persisted.
293	     */
294	    public int getCheckDigit() {
295	        return LuhnCheckDigit.of(this.customerCode);
296	    }
297	
298	    /**
299	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
300	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
301	     */
302	    public String getContactPreference() {
303	        return hasEmail() ? "EMAIL" : "PHONE";
304	    }
305	
306	    /**
307	     * The owner's identity key: a composite fingerprint formed as the normalized telephone,
308	     * the email (or empty when absent) and the household id (or empty when none), joined by
309	     * {@code '|'}. Derived from stored state, never persisted.
310	     */
311	    public String getIdentityKey() {
312	        String emailPart = hasEmail() ? this.email : "";
313	        String householdPart = this.householdId == null ? "" : this.householdId;
314	        return this.telephone + "|" + emailPart + "|" + householdPart;
315	    }
316	
317	    private boolean hasEmail() {
318	        return this.email != null && !this.email.isEmpty();
319	    }
320	
321	    protected Set<Pet> getPetsInternal() {
322	        if (this.pets == null) {
323	            this.pets = new HashSet<>();
324	        }
325	        return this.pets;
326	    }
327	
328	    protected void setPetsInternal(Set<Pet> pets) {
329	        this.pets = pets;
330	    }
331	
332	    public List<Pet> getPets() {
333	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
334	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
335	        return Collections.unmodifiableList(sortedPets);
336	    }
337	
338	    public void setPets(List<Pet> pets) {
339	        this.pets = new HashSet<>(pets);
340	    }
341	
342	    public void addPet(Pet pet) {
343	        getPetsInternal().add(pet);
344	        pet.setOwner(this);
345	    }
346	
347	    /**
348	     * Return the Pet with the given name, or null if none found for this Owner.
349	     *
350	     * @param name to test
351	     * @return true if pet name is already in use
352	     */
353	    public Pet getPet(String name) {
354	        return getPet(name, false);
355	    }
356	
357	    /**
358	     * Return the Pet with the given name, or null if none found for this Owner.
359	     *
360	     * @param name to test
361	     * @return true if pet name is already in use
362	     */
363	    public Pet getPet(String name, boolean ignoreNew) {
364	        name = name.toLowerCase();
365	        for (Pet pet : getPetsInternal()) {
366	            if (!ignoreNew || !pet.isNew()) {
367	                String compName = pet.getName();
368	                compName = compName.toLowerCase();
369	                if (compName.equals(name)) {
370	                    return pet;
371	                }
372	            }
373	        }
374	        return null;
375	    }
376	
377	    public Pet getPet(Integer petId) {
378	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
379	    }
380	
381	    @Override
382	    public String toString() {
383	        return new ToStringCreator(this)
384	
385	            .append("id", this.getId())
386	            .append("new", this.isNew())
387	            .append("lastName", this.getLastName())
388	            .append("firstName", this.getFirstName())
389	            .append("address", this.address)
390	            .append("city", this.city)
391	            .append("telephone", this.telephone)
392	            .toString();
393	    }
394	}
