3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	import org.springframework.samples.petclinic.util.E164PhoneNumber;
7	
8	/**
9	 * Normalizes an owner request's telephone to E.164 form, rejecting anything that cannot
10	 * form a valid E.164 number with a 400. Runs after the request's presence has been
11	 * confirmed, and mutates the shared request in place so downstream steps
12	 * ({@link BuildOwner} / {@link ApplyOwner}) store, and the possible-duplicate check
13	 * ({@link AssignOwnerPossibleDuplicate}) compares, the E.164 value.
14	 */
15	public class NormalizeOwnerTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
18	        String e164 = E164PhoneNumber.toE164(request.getTelephone())
19	                .orElseThrow(() -> new InvalidTelephoneException(request.getTelephone()));
20	        request.setTelephone(e164);
21	    }
22	}
