8	/**
9	 * Rejects an owner request whose (already E.164-normalized) telephone has a
10	 * national-number length that is wrong for its country code, with a 400. Runs after
11	 * {@link NormalizeOwnerTelephone} so it sees the canonical '+'-prefixed value.
12	 */
13	public class ValidateOwnerTelephoneLength {
14	
15	    public void service(@Val OwnerFieldsDto request) throws TelephoneNationalNumberLengthException {
16	        if (!E164PhoneNumber.hasValidNationalNumberLength(request.getTelephone())) {
17	            throw new TelephoneNationalNumberLengthException(request.getTelephone());
18	        }
19	    }
20	}
